(function(root){
 'use strict';
 const PAGE_SIZE=100;
 const SOURCE_LABELS={'daily-total':'Дневные снимки — товары','daily-warehouse':'Дневные снимки — склады','audit-total':'Внутридневная история — товары','audit-warehouse':'Внутридневная история — склады','diagnostic-warehouse':'Архив API за август — неполные выборки','cabinet-total':'Итог кабинета','cabinet-warehouse':'Кабинет по складам','seller-warehouse':'Склады продавца','cluster-warehouse':'Склады по кластерам'};
 const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
 const known=value=>value!==null&&value!==undefined&&value!=='';
 function create(options={}){
  const doc=options.document||root.document,fetcher=options.fetch||root.fetch?.bind(root),location=options.location||root.location;
  const $=id=>doc.getElementById(id);let offset=0,total=0,requestVersion=0,ready=false,status=null;
  const params=new URLSearchParams(location?.search||'');
  function fmtNumber(value){return known(value)?new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(Number(value)):'—'}
  function fmtDate(value){if(!known(value))return '—';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
  function fmtDay(value){if(!known(value))return '—';const date=new Date(String(value).slice(0,10)+'T12:00:00Z');return Number.isNaN(date.getTime())?String(value):date.toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'})}
  async function json(url){const response=await fetcher(url,{headers:{Accept:'application/json'}});let value={};try{value=await response.json()}catch{}if(!response.ok){const error=new Error(value.error||'Не удалось загрузить данные');error.status=response.status;throw error}return value}
  function setNotice(message,error=false){$('stock-notice').textContent=message;$('stock-notice').className='stock-notice'+(error?' error':'')}
  function filters(includePage=true){const query=new URLSearchParams({source:$('stock-source').value||'daily-total'});for(const [name,id] of [['store','stock-store'],['sku','stock-sku'],['q','stock-query'],['from','stock-from'],['to','stock-to']]){const value=id==='stock-sku'?params.get('sku'):$((id)).value;if(value)query.set(name,value)}if(includePage){query.set('limit',String(PAGE_SIZE));query.set('offset',String(offset))}return query}
  function syncUrl(){if(!root.history?.replaceState)return;const query=filters(false);root.history.replaceState(null,'',location.pathname+(query.toString()?'?'+query:''))}
  function renderStatus(data){status=data;$('stock-range').textContent=data.from&&data.to?fmtDay(data.from)+' — '+fmtDay(data.to):'—';$('stock-records').textContent=fmtNumber(data.records);$('stock-products').textContent=fmtNumber(data.products);for(const id of ['stock-from','stock-to']){const input=$(id);input.min=data.from||'';input.max=data.to||''}if(!$('stock-from').value)$('stock-from').value=data.from||'';if(!$('stock-to').value)$('stock-to').value=data.to||'';
   const selected=$('stock-store').value||params.get('store')||'',stores=Array.isArray(data.stores)?data.stores:[];$('stock-store').innerHTML='<option value="">Все магазины Ozon</option>'+stores.map(store=>`<option value="${esc(store.id)}">${esc(store.name)}</option>`).join('');if(stores.some(store=>String(store.id)===selected))$('stock-store').value=selected;
  }
  function quality(row){const value=row.quality;if(!known(value))return '—';if(typeof value==='string')return esc(value);if(typeof value==='object'){const label=value.label??value.status??value.condition;if(known(label))return esc(label)}return esc(String(value))}
  function renderRows(data){const rows=Array.isArray(data.rows)?data.rows:[];total=Number.isFinite(Number(data.total))?Number(data.total):0;const sourceLabel=data.sourceLabel||SOURCE_LABELS[data.source]||SOURCE_LABELS[$('stock-source').value]||$('stock-source').value;
   $('stock-source-note').textContent='Выбран один источник: '+sourceLabel+(params.get('sku')?' · точный фильтр SKU '+params.get('sku'):'')+'. Значения показаны как в снимке и не агрегируются.';
   $('stock-rows').innerHTML=rows.map(row=>`<tr><td><span class="stock-cell-title">Дневная запись: ${esc(fmtDay(row.day))}</span><span class="stock-cell-sub">Наблюдение: ${esc(fmtDate(row.observedAt))} МСК</span></td><td><span class="stock-cell-title">${esc(row.storeName||'—')}</span><span class="stock-cell-sub">${esc(row.storeId||'')}</span></td><td><span class="stock-cell-title">${esc(row.name||row.article||'Без названия')}</span><span class="stock-cell-sub">${row.article?'Арт. '+esc(row.article)+' · ':''}SKU ${esc(row.sku||'—')}</span></td><td><span class="stock-cell-title">${esc(row.warehouse||'—')}</span><span class="stock-cell-sub">${row.cluster?'Кластер: '+esc(row.cluster):row.warehouseId?'ID: '+esc(row.warehouseId):''}</span></td><td class="numeric">${fmtNumber(row.totalStock)}</td><td class="numeric">${fmtNumber(row.available)}</td><td class="numeric">${fmtNumber(row.inTransit)}</td><td class="numeric">${fmtNumber(row.reserved)}</td><td><span class="stock-quality${row.quality==='ok'?' good':''}">${quality(row)}</span><span class="stock-cell-sub">${esc(row.sourceLabel||sourceLabel)}</span></td></tr>`).join('')||'<tr><td colspan="9" class="stock-empty">В выбранном источнике нет строк по этим условиям. Это не означает нулевой остаток.</td></tr>';
   const pages=Math.max(1,Math.ceil(total/PAGE_SIZE)),page=Math.floor(offset/PAGE_SIZE)+1;$('stock-count').textContent=total?`${new Intl.NumberFormat('ru-RU').format(offset+1)}–${new Intl.NumberFormat('ru-RU').format(Math.min(offset+rows.length,total))} из ${new Intl.NumberFormat('ru-RU').format(total)} строк`:'Найдено 0 строк';$('stock-page').textContent=page+' / '+pages;$('stock-prev').disabled=offset===0;$('stock-next').disabled=offset+rows.length>=total;$('stock-export').disabled=!rows.length;
   const limitations=[...(Array.isArray(status?.limitations)?status.limitations:[]),...(Array.isArray(data.limitations)?data.limitations:[])].filter((item,index,list)=>item&&list.indexOf(item)===index);$('stock-limitations').hidden=!limitations.length;$('stock-limitations').innerHTML=limitations.length?'<strong>Ограничения данных</strong><ul>'+limitations.map(item=>'<li>'+esc(item)+'</li>').join('')+'</ul>':'';
  }
  async function loadReport(){const version=++requestVersion;setNotice('Загружаем строки выбранного источника…');try{const data=await json('/api/stock-history/report?'+filters());if(version!==requestVersion)return;renderRows(data);syncUrl();setNotice(data.rows?.length?'Показаны исторические снимки Ozon. Количества не суммированы.':'Строк по выбранным условиям нет. Нулевой остаток из этого не следует.')}catch(error){if(version!==requestVersion)return;$('stock-rows').innerHTML='<tr><td colspan="9" class="stock-empty">'+(error.status===404?'Отчёт истории остатков ожидает обновления сервера.':'Не удалось загрузить отчёт.')+'</td></tr>';$('stock-export').disabled=true;setNotice(error.status===404?'Отчёт истории остатков ожидает обновления сервера. Перезапустите обновлённый Пульт.':error.message,true)}}
  async function init(){try{const data=await json('/api/stock-history/status');renderStatus(data);ready=true;setNotice(data.importedAt?'Импорт завершён '+fmtDate(data.importedAt)+'. Загружаем строки…':'Снимки ещё не импортированы.');await loadReport()}catch(error){setNotice(error.status===404?'История остатков ожидает обновления сервера. Перезапустите обновлённый Пульт.':error.message,true);$('stock-rows').innerHTML='<tr><td colspan="9" class="stock-empty">Отчёт истории остатков ожидает обновления сервера.</td></tr>'}}
  async function exportCsv(){const button=$('stock-export');button.disabled=true;try{const response=await fetcher('/api/stock-history/export?'+filters(false),{headers:{Accept:'text/csv'}});if(!response.ok)throw Error('Не удалось подготовить CSV');const blob=await response.blob(),url=root.URL.createObjectURL(blob),link=doc.createElement('a');link.href=url;link.download='Пульт-история-остатков-'+new Date().toISOString().slice(0,10)+'.csv';link.click();root.setTimeout(()=>root.URL.revokeObjectURL(url),1000);setNotice('CSV подготовлен. В нём сохранён выбранный источник без суммирования строк.')}catch(error){setNotice(error.message,true)}finally{button.disabled=total===0}}
  $('stock-source').value=SOURCE_LABELS[params.get('source')]?params.get('source'):'daily-total';$('stock-query').value=params.get('q')||'';$('stock-from').value=params.get('from')||'';$('stock-to').value=params.get('to')||'';
  $('stock-filters').addEventListener('submit',event=>{event.preventDefault();offset=0;if(ready)void loadReport()});$('stock-reset').addEventListener('click',()=>{$('stock-source').value='daily-total';$('stock-store').value='';$('stock-query').value='';params.delete('sku');$('stock-from').value=status?.from||'';$('stock-to').value=status?.to||'';offset=0;if(ready)void loadReport()});$('stock-prev').addEventListener('click',()=>{offset=Math.max(0,offset-PAGE_SIZE);void loadReport()});$('stock-next').addEventListener('click',()=>{offset+=PAGE_SIZE;void loadReport()});$('stock-export').addEventListener('click',exportCsv);void init();
  return {loadReport,filters,renderRows,get state(){return {offset,total,requestVersion}}};
 }
 root.createPultStockHistory=create;if(root.document?.getElementById('stock-filters'))create();
})(typeof window!=='undefined'?window:globalThis);
